#!/usr/bin/env node
/**
 * Copy the canonical brand assets and locale catalogs into `src/`.
 *
 * The same pattern the console uses, for the same reason: the canonical assets
 * live at the repository root so a designer edits one place, and the app copies
 * them in at build time rather than importing across the project root.
 *
 * `src/assets/` and `src/locales/` are gitignored and regenerated by the npm
 * `pre*` hooks.
 */
import { cpSync, existsSync, mkdirSync, readdirSync, rmSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '..', '..', '..');
const sources = [
  { from: join(root, 'media'), to: resolve(here, '..', 'src', 'assets'), pattern: /\.svg$/ },
  { from: join(root, 'i18n', 'locales'), to: resolve(here, '..', 'src', 'locales'), pattern: /\.json$/ },
];

for (const source of sources) {
  if (!existsSync(source.from)) {
    console.error(`[sync-assets] not found: ${source.from}`);
    process.exit(1);
  }
  const files = readdirSync(source.from).filter((name) => source.pattern.test(name));
  if (files.length === 0) {
    console.error(`[sync-assets] no matching files in ${source.from}`);
    process.exit(1);
  }
  rmSync(source.to, { recursive: true, force: true });
  mkdirSync(source.to, { recursive: true });
  for (const name of files) {
    cpSync(join(source.from, name), join(source.to, name));
  }
  console.log(`[sync-assets] copied ${files.length} file(s) from ${source.from}`);
}
